#!/usr/bin/env node
// Gate for the live front page: checks the root README.md against the repository it describes.
//   node tools/front-page/check.mjs [--json] [README.md]
// Exits 1 on any failure. The README is generated by docs/front-page/arcade-floor/src/readme.mjs:
// fix failures there, not in README.md. See tools/front-page/README.md.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { SAFE, codeBlocks, colWidth, lintSvg, references } from './lib/lint.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

// Total page weight: the README plus every local image it loads once.
export const WEIGHT_BUDGET = 3 * 1024 * 1024;

// Words that make the page read as a piracy release. Case-insensitive.
export const PIRACY = [
  /\bcrack(?:s|ed|er|ers|ing|tros?)?\b/i, /\bkeygens?\b/i, /\bwarez\b/i, /\bserials?\b/i, /\bcracked by\b/i,
  /\bsupplied by\b/i, /\bpresents\b/i, /\bswappers?\b/i, /\bnuked?\b/i, /\bpirat\w*/i, /\bphreak\w*/i,
  /\b0-?day\b/i,
];
// Real scene groups and productions. Case-sensitive where the name is also an ordinary word.
export const GROUPS = [
  /\bRazor ?1911\b/i, /\bFairlight\b/i, /\bTRSI\b/, /\bRed Sector\b/i, /\bKefrens\b/i, /\bFuture Crew\b/i,
  /\bSkid ?Row\b/i, /\bSKIDROW\b/, /\bReloaded\b/, /\bRELOADED\b/, /\bParadox\b/, /\bQuartex\b/i, /\bScoopex\b/i,
  /\bMelon Dezign\b/i, /\bHoodlum\b/i, /\bHOODLUM\b/, /\bDeviance\b/, /\bDEVIANCE\b/, /\bTristar\b/i, /\bIkari\b/i,
  /\bHokuto Force\b/i, /\bSkillion\b/i, /\bDream Team\b/, /\bPhenomena\b/, /\bSpaceballs\b/i, /\bSilents\b/,
  /\bFarbrausch\b/i, /\bConspiracy\b/, /\bHaujobb\b/i, /\bCensor Design\b/i, /\bBooze Design\b/i, /\bOxyron\b/i,
  /\bGenesis Project\b/, /\bDrinkOrDie\b/i, /\bACiD\b/, /\bBlocktronics\b/i, /\bMistigris\b/i, /\bSanity\b/,
  /\bCrionics\b/i, /\bCascada\b/, /\bByterapers\b/i, /\bRemorse\b/, /\bSecond Reality\b/i, /\bClass\b.*\bgroup\b/i,
];
// Not listed: CODEX, a release group that shares its name with the Codex agent this tool drives.

const strip = (s) => s.replace(/<!--[\s\S]*?-->/g, '');

export function denyHits(text, where) {
  const hits = [];
  for (const re of PIRACY) { const m = text.match(re); if (m) hits.push(`${where}: piracy word "${m[0]}"`); }
  for (const re of GROUPS) { const m = text.match(re); if (m) hits.push(`${where}: real group name "${m[0]}"`); }
  return hits;
}

// Every `npx readme-nfo ...` invocation shown (HTML comments aside), with its arguments.
export function commandsIn(markdown) {
  const out = [];
  for (const m of strip(markdown).matchAll(/npx readme-nfo((?:[ \t]+(?:<[a-z]+>|[A-Za-z0-9_./:-]+(?=[\s`"*),.;:]|$)))*)/gi)) {
    const args = m[1].trim().split(/\s+/).filter(Boolean).map((a) => a.replace(/[.,;:]+$/, ''));
    out.push({ text: m[0].trim(), args });
  }
  return out;
}

export function checkCommand({ text, args }, caps, helpFlags) {
  const problems = [];
  const commands = new Set(caps.commands.filter((c) => !c.startsWith('(')));
  const flags = new Set([...(caps.agents?.flags || []), ...helpFlags]);
  let first = true;
  for (const arg of args) {
    if (/^--[a-z]/.test(arg)) { if (!flags.has(arg)) problems.push(`${text}: unknown flag ${arg}`); }
    else if (/^-\d+$/.test(arg)) { if (!flags.has('-N')) problems.push(`${text}: count flag ${arg} not supported`); }
    else if (first && /[/.]/.test(arg)) { if (!caps.project?.urlMode) problems.push(`${text}: URL mode not supported`); }
    else if (first && !/^\d+$/.test(arg) && !/^<.*>$/.test(arg)) { if (!commands.has(arg)) problems.push(`${text}: unknown command "${arg}"`); }
    first = false;
  }
  return problems;
}

// Count claims: "153 styles", "STYLES ...... 153", "TOTAL 260 HEADERS", "STYLES 153/153", and the
// HIGH SCORES rows "1ST 116 CASTAWAY". Returns [{ kind, value, text }].
export function countClaims(text) {
  const claims = [];
  const kinds = { style: 'styles', styles: 'styles', family: 'families', families: 'families', header: 'headers', headers: 'headers', gallery: 'galleries', galleries: 'galleries' };
  for (const m of text.matchAll(/\b(\d[\d,]*)[ \t]+(?:[a-z-]+[ \t]+)?(styles?|famil(?:y|ies)|headers?|galler(?:y|ies))\b/gi)) {
    claims.push({ kind: kinds[m[2].toLowerCase()], value: Number(m[1].replace(/,/g, '')), text: m[0], batchOk: true });
  }
  for (const m of text.matchAll(/\b(STYLES|FAMILIES|HEADERS|GALLERIES|HI-SCORE)[ \t]*\.{2,}[ \t]*(\d+)/g)) {
    claims.push({ kind: m[1] === 'HI-SCORE' ? 'headers' : m[1].toLowerCase(), value: Number(m[2]), text: m[0] });
  }
  for (const m of text.matchAll(/\bSTYLES[ \t]+(\d+)\/(\d+)/g)) {
    claims.push({ kind: 'styles', value: Number(m[1]), text: m[0] }, { kind: 'styles', value: Number(m[2]), text: m[0] });
  }
  for (const m of text.matchAll(/^\d+(?:ST|ND|RD|TH)[ \t]+(\d+)[ \t]+(\S.*?)[ \t]*$/gm)) {
    claims.push({ kind: 'gallery', gallery: m[2].trim().toLowerCase().replace(/[\s.]+/g, '-'), value: Number(m[1]), text: m[0].trim() });
  }
  return claims;
}

// The same facts the front-page builds compute: tracked header pages (logo sets are not galleries).
export async function repoFacts(root = ROOT) {
  const { loadCatalogue } = await import(pathToFileURL(path.join(root, 'tools/generator/hybrid-catalogue.mjs')).href);
  const catalogue = loadCatalogue();
  const source = JSON.parse(fs.readFileSync(path.join(root, 'styles/styles.json'), 'utf8'));
  const perSet = {};
  for (const f of execFileSync('git', ['ls-files', 'examples'], { cwd: root, encoding: 'utf8' }).split('\n')) {
    const m = f.match(/^examples\/([^/]+)\/\d+-[^/]+\.md$/);
    if (m && !/-logos-/.test(m[1])) perSet[m[1]] = (perSet[m[1]] || 0) + 1;
  }
  return {
    styles: catalogue.distinct.length,
    families: source.families.length,
    headers: Object.values(perSet).reduce((a, b) => a + b, 0),
    galleries: Object.keys(perSet).length,
    perSet,
  };
}

function capabilities(root) {
  const run = (args) => execFileSync(process.execPath, [path.join(root, 'tools/generate.mjs'), ...args], { cwd: root, encoding: 'utf8' });
  const caps = JSON.parse(run(['--capabilities', '--json']));
  const help = run(['--help']);
  const helpFlags = new Set(help.match(/--[a-z][a-z-]*/g) || []);
  if (/-N\b/.test(help)) helpFlags.add('-N');
  return { caps, helpFlags };
}

const svgText = (file) => {
  const src = fs.readFileSync(file, 'utf8');
  return [...src.matchAll(/<(title|desc)\b[^>]*>([\s\S]*?)<\/\1>/g)].map((m) => m[2]).join(' ');
};

export async function checkReadme(readmePath = path.join(ROOT, 'README.md'), root = ROOT) {
  const markdown = fs.readFileSync(readmePath, 'utf8');
  const base = path.dirname(readmePath);
  const sections = {};
  const add = (name, problems, info) => { sections[name] = { ok: !problems.length, problems, info }; };

  // 1. Local links and images.
  const missing = [];
  const images = new Map();
  let links = 0;
  for (const { ref, image } of references(markdown)) {
    if (/^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i.test(ref)) continue;
    const clean = decodeURIComponent(ref.split(/[?#]/)[0]);
    if (!clean) continue;
    links++;
    const target = path.resolve(base, clean);
    if (!fs.existsSync(target)) missing.push(`missing ${image ? 'image' : 'link target'}: ${ref}`);
    else if (image) images.set(target, clean);
  }
  add('links', missing, `${links} local links and images`);

  // 2. Code blocks: 80 columns, safe glyphs.
  const code = [];
  const blocks = codeBlocks(markdown);
  for (const [n, b] of blocks.entries()) {
    const width = Math.max(0, ...b.lines.map(colWidth));
    if (width > 80) code.push(`code block ${n + 1} (line ${b.line}): ${width} columns, over 80`);
    for (const [k, l] of b.lines.entries()) for (const ch of l) {
      const cp = ch.codePointAt(0);
      if (!SAFE(cp)) { code.push(`code block ${n + 1} line ${b.line + k + 1}: U+${cp.toString(16).toUpperCase().padStart(4, '0')} "${ch}" outside the safe set`); break; }
    }
  }
  add('code', code, `${blocks.length} code blocks`);

  // 3. Deny list: the page (alt text included) and the accessible text of every SVG it shows.
  const deny = [...denyHits(markdown, 'README')];
  for (const m of markdown.matchAll(/\balt="([^"]*)"/g)) deny.push(...denyHits(m[1], `alt "${m[1].slice(0, 40)}"`));
  for (const [file, rel] of images) if (/\.svg$/i.test(file)) deny.push(...denyHits(svgText(file), `${rel} title/desc`));
  add('deny', [...new Set(deny)], 'piracy words and real group names');

  // 4. Counts.
  const facts = await repoFacts(root);
  const { caps, helpFlags } = capabilities(root);
  const batch = caps.batch?.defaultCount;
  const counts = [];
  const texts = [strip(markdown), ...[...images].filter(([f]) => /\.svg$/i.test(f)).map(([f]) => svgText(f))];
  const claims = texts.flatMap(countClaims);
  for (const c of claims) {
    if (c.kind === 'gallery') {
      if (!(c.gallery in facts.perSet)) counts.push(`"${c.text}": no gallery named ${c.gallery}`);
      else if (facts.perSet[c.gallery] !== c.value) counts.push(`"${c.text}": ${c.gallery} has ${facts.perSet[c.gallery]} headers`);
      continue;
    }
    if (c.value === facts[c.kind]) continue;
    if (c.batchOk && (c.kind === 'headers' || c.kind === 'styles') && c.value === batch) continue; // "10 new styles"
    counts.push(`"${c.text}": the repo has ${facts[c.kind]} ${c.kind}`);
  }
  add('counts', counts, `${claims.length} claims; repo has ${facts.styles} styles, ${facts.families} families, ${facts.headers} headers, ${facts.galleries} galleries`);

  // 5. Commands.
  const shown = commandsIn(markdown);
  add('commands', shown.flatMap((c) => checkCommand(c, caps, helpFlags)), `${shown.length} npx readme-nfo commands`);

  // 6. Reduced motion, and 7. weight.
  const motion = [];
  let animated = 0;
  let bytes = Buffer.byteLength(markdown);
  for (const [file, rel] of images) {
    bytes += fs.statSync(file).size;
    if (!/\.svg$/i.test(file)) continue;
    const svg = lintSvg(file);
    if (svg.animated) animated++;
    if (svg.animated && !/prefers-reduced-motion/i.test(fs.readFileSync(file, 'utf8'))) motion.push(`${rel}: animated without a prefers-reduced-motion fallback`);
  }
  add('motion', motion, `${animated} animated SVGs`);
  const kb = (n) => `${(n / 1024).toFixed(0)} KB`;
  add('weight', bytes > WEIGHT_BUDGET ? [`page weighs ${kb(bytes)}, over the ${kb(WEIGHT_BUDGET)} budget`] : [], `${kb(bytes)} of ${kb(WEIGHT_BUDGET)} (README and ${images.size} images)`);

  return { ok: Object.values(sections).every((s) => s.ok), readme: path.relative(root, readmePath).split(path.sep).join('/') || 'README.md', sections };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const target = args.find((a) => !a.startsWith('--'));
  const result = await checkReadme(target ? path.resolve(target) : undefined);
  if (args.includes('--json')) console.log(JSON.stringify(result, null, 2));
  else {
    console.log(`Front page: ${result.readme}`);
    for (const [name, s] of Object.entries(result.sections)) {
      console.log(`  ${s.ok ? 'ok  ' : 'FAIL'} ${name.padEnd(9)}${s.info}`);
      for (const p of s.problems) console.log(`         - ${p}`);
    }
    console.log(result.ok ? 'Front page check passed.' : 'Front page check failed: fix docs/front-page/arcade-floor/src/readme.mjs and rebuild.');
  }
  process.exitCode = result.ok ? 0 : 1;
}
